async function api(route,method='GET',body=null,key=null){const opts={method,credentials:'same-origin',headers:{'X-CSRFToken':csrf()}};if(method!=='GET'){opts.headers['Idempotency-Key']=key||crypto.randomUUID();if(body instanceof FormData)opts.body=body;else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body||{})}}const r=await fetch('/api/v1/'+route,opts);let result;try{result=await r.json()}catch{throw new Error('Connection unavailable. Please try again shortly')}if(!r.ok){if(r.status===401)location.href='/login/';const e=new Error(result.error?.message||'Operation failed');e.code=result.error?.code;e.fields=result.error?.field_errors;e.requestId=result.request_id;throw e}return result}
